params.script_inline:
"""The enrolment of a simple-agent@2 at the colony's affinity (OR-AG-2).

A manifest sends no message, and `subscribe` takes its subscriber from the edge
(affinity README, "Identity comes from the edge"), so the agent enrols itself:
on a mutation receipt (`mutation_committed`) that concerns the agent itself --
the boot's (`form: boot`), or one whose `paths` name a node at, under or above
the agent or whose `scopes` name one at or under it (GH #1312) -- this cell writes the agent's entry, its disclosures and its subscriptions through the
rim lane `affinity_propose`, one step after the acknowledgement of the one
before (an entry must exist before a disclosure names it). Every op is an
upsert or an append that newest-wins, so a receipt that comes again writes
the same rows again and duplicates nothing; a receipt of a mutation elsewhere
in the colony writes nothing (OR-AG-48: each `subscribe` books a new row and
pushes a pack, so idempotent is not free). Cold (`passes=rare`): a receipt is
rare, and the step travels in `context.sa_enrol`, so no child keeps state.

Turns never wait for this: the door has no boot gate, and until the first pack
the agent speaks without the identity slot.

stdin is {envelope, body, params}; stdout a JSON array of content documents.
"""
import json
import sys

doc = json.load(sys.stdin)
P = doc.get("params") or {}
HEADER = (doc.get("envelope") or {}).get("header") or {}
HOP = HEADER.get("hop") or {}
CTX = HEADER.get("context") or {}


def _obj(v):
    return v if isinstance(v, dict) else {}


def agent_id():
    return str(P.get("agent_id") or "agent")


def display_name(identity):
    names = _obj(_obj(identity.get("identity")).get("names"))
    parts = [str(names.get(k) or "") for k in ("first", "last")]
    return " ".join(p for p in parts if p) or str(names.get("nickname") or "") or agent_id()


def propose(step, op_args):
    """One write into the colony affinity's entry of this agent: a `tool_call` turn whose
    text is the op, as `in_propose` takes it. The actor and, for `subscribe`, the
    subscriber are the embedder's edge's (`hop.agent_id`, `context.sa_enrol`)."""
    head = {"route": "affinity_propose", "sa_rim": "out", "agent_id": agent_id(), "sa_enrol": step}
    return {"header": head, "messages": [{"origin": "assistant", "type": "tool_call",
                                          "id": "enrol-%s" % step, "text": json.dumps(op_args)}]}


def charter():
    return _obj(P.get("charter"))


def disclosures():
    """`disclose` entries: a field path (released to the agent itself), or
    `{field_path, audience?, audience_set?, mode?}`. With a charter its subtree
    `mx.brain` is released to the agent as well: without the row the renderer
    delivers nothing of it (affinity README, fail-closed)."""
    me = "agent:%s" % agent_id()
    out = []
    entries = P.get("disclose")
    for e in (entries if isinstance(entries, list) else ["aieos"]):
        e = {"field_path": e} if isinstance(e, str) else _obj(e)
        path = str(e.get("field_path") or "")
        if not path:
            continue
        audience = str(e.get("audience") or me)
        aset = e.get("audience_set") if isinstance(e.get("audience_set"), list) else [audience]
        out.append({"op": "set_disclosure", "entity_id": "entity:%s" % agent_id(),
                    "field_path": path, "audience": audience, "audience_set": aset,
                    "mode": str(e.get("mode") or "share")})
    if charter() and not any(d["field_path"] == "mx.brain" for d in out):
        out.append({"op": "set_disclosure", "entity_id": "entity:%s" % agent_id(),
                    "field_path": "mx.brain", "audience": me, "audience_set": [me],
                    "mode": "share"})
    return out


def subscriptions():
    """`identity` and `brain` cannot travel in one request (affinity README,
    `slots_conflict`), so a charter is a second subscription of its own."""
    subject = "entity:%s" % agent_id()
    out = [propose("subscribe", {"op": "subscribe", "subject": subject, "slots": ["identity"]})]
    if charter():
        out.append(propose("subscribe_brain", {"op": "subscribe", "subject": subject,
                                               "slots": ["brain"]}))
    return out


def _strings(value):
    return [str(v).rstrip("/") or "/" for v in value] if isinstance(value, list) else None


def concerns_me():
    """The receipt is the agent's own: the boot, or a knock that wrote at it.

    Since GH #1312 a receipt names where the knock wrote: `paths`, every node
    it added, removed, replaced, swapped in or moved, and `scopes`, every
    declaration's scope. A node at the agent, under it or ABOVE it (the agent
    was born or lifted with it -- a figure grown by one `add_nodes` at the
    member, the agent one level deeper inside it) or a scope at or under the
    agent (its own graph was written) is its own. A scope above it is not: a
    builder block elsewhere in the same member or an announcement at the
    colony's container writes nothing of the agent's (OR-AG-48, each
    `subscribe` books a row and pushes a pack).

    A receipt without the two keys (a colony before GH #1312) keeps the old
    reading: every manifest, and a single knock whose scope is the agent,
    under it, or its parent level."""
    if HOP.get("form") == "boot":
        return True
    target = str((doc.get("envelope") or {}).get("target") or "")
    me = target.rsplit("/", 1)[0] if target.count("/") > 1 else ""
    if not me:
        return False
    paths, scopes = _strings(HOP.get("paths")), _strings(HOP.get("scopes"))
    if paths is not None and scopes is not None:
        def at_or_under(p):
            return p == me or p.startswith(me + "/")
        return any(at_or_under(p) or me.startswith(p.rstrip("/") + "/") for p in paths) \
            or any(at_or_under(s) for s in scopes)
    if HOP.get("form") == "manifest":
        return True
    scope = str(HOP.get("scope") or "")
    if not scope.startswith("/"):
        return False
    parent = me.rsplit("/", 1)[0] or "/"
    return scope == me or scope.startswith(me + "/") or scope.rstrip("/") == parent.rstrip("/")


def on_receipt():
    if not concerns_me():
        return []
    identity = _obj(P.get("identity"))
    if not identity:
        return []  # nothing to enrol: the agent speaks without an identity slot
    return [propose("upsert", {"op": "upsert_entity", "entity_id": "entity:%s" % agent_id(),
                               "kind": "agent", "display_name": display_name(identity),
                               "aieos": identity, "mx": {"brain": charter()}})]


def on_ack(step):
    if HOP.get("propose_outcome") == "error" or str(HOP.get("outcome") or "") != "accepted":
        # Loud, never silent; the turns are not held by it.
        return [{"header": {"route": "error", "sa_rim": "out"},
                 "error": {"error_code": "enrol_refused", "step": step,
                           "reason_code": str(HOP.get("reason_code") or "")},
                 "messages": [{"origin": "assistant", "type": "text", "text": "error"}]}]
    if step == "upsert":
        ds = disclosures()
        if not ds:
            return subscriptions()
        return [propose("disclose:%d:%d" % (i, len(ds)), d) for i, d in enumerate(ds)]
    if step.startswith("disclose:"):
        _, i, n = (step.split(":") + ["0", "0"])[:3]
        # Acks come back in the order the writes left; the last one opens the subscription.
        return subscriptions() if i.isdigit() and n.isdigit() and int(i) == int(n) - 1 else []
    return []


route = HOP.get("route")
if route == "mutation_committed":
    out = on_receipt()
elif route == "in_propose_ack" and CTX.get("sa_enrol"):
    out = on_ack(str(CTX.get("sa_enrol")))
else:
    out = []
sys.stdout.write(json.dumps(out))
